import pages as PG
from pages import *
from pages import foreword,glance,reading,story,cards,end,sources,build,covart,verse
from fx import *
PG.configure('/ganesha/festivals/gauri-ganesha-habba/',[('','Gaurī-Gaṇeśa Habba','Karnataka’s Mother-and-Son Festival')],'red','Gaurī-Gaṇeśa','Devī','Gaurī-Gaṇeśa')
PG.CFG.update(backurl='/ganesha/festivals/',backname='Gaṇeśa festivals')
PG.OUT='outd/gauri-ganesha-habba/'
i=0
GAU=lambda: devi(sari='#2a9d6f',items=('lotus','abhaya'))
def mora(): return '<path d="M-30 0 q30 14 60 0 l-8 -18 h-44z" fill="#e0c060"/>'+''.join(f'<circle cx="{x}" cy="-14" r="4" fill="{c}"/>' for x,c in [(-14,'#e0a800'),(-4,'#c0392b'),(6,'#2a9d6f'),(16,'#fff')])
def tank(): return '<ellipse rx="50" ry="14" fill="#8fb8de"/><ellipse rx="50" ry="14" fill="none" stroke="#6a8ab0" stroke-width="3"/>'
def gauri_plate(): return plate()+g(0,-6,.5,GAU())
def thread16(): return '<path d="M-36 0 q36 -24 72 0" fill="none" stroke="#e0a800" stroke-width="3"/>'+''.join(f'<circle cx="{-34+k*4.5:.1f}" cy="{-12*__import__("math").sin(k*0.2):.1f}" r="1.8" fill="#c0392b"/>' for k in range(16))
COV=covart('Gaurī as a decorated image beside a small Gaṇeśa, with bāgina trays in winnows, banana stems and a toraṇa',f'<rect width="440" height="196" fill="#f6e3e1"/>'+'<rect y="160" width="440" height="36" fill="#e9c9c3"/>'+''.join(f'<path d="M{x} 20 q-6 18 0 30 q6 -12 0 -30z" fill="#2f7a3a"/>' for x in range(20,440,22))+'<path d="M0 20 h440" stroke="#6a4a2a" stroke-width="3"/>'+'<path d="M120 186 v-110 M320 186 v-110" stroke="#7a9a3a" stroke-width="10"/>'+g(190,180,1.4,GAU())+g(270,184,1.2,ganesha())+g(70,186,1.3,mora())+g(380,186,1.3,mora()))
pp=[foreword(i,['In Karnataka the Gaṇeśa festival is two festivals. On the third day of the bright fortnight of Bhādrapada, <b>Gaurī</b>, the mother, arrives, welcomed like a married daughter visiting her parents. On the fourth, her son <b>Gaṇeśa</b> follows, to take her home. Together they are <b>Gaurī-Gaṇeśa habba</b>, the most homely festival of the Kannada year.','Gaurī’s day belongs to the women: the <b>Svarṇa Gaurī vrata</b>, the sixteen-knot thread, the <b>bāgina</b> trays given to married women, and gifts from parents to their married daughters. This article explains who Gaurī is, tells her stories and the vrata story, gives the Devī Māhātmya’s great verse to her, and walks through both days in a Karnataka home.'],[('z','Why does Gaurī come first?'),('b','Because she’s his mother, Zappy. In Karnataka the son comes the next day to take her home.')]),
 glance([('When','Bhādrapada Śukla Tṛtīyā (Gaurī) and Caturthī (Gaṇeśa); August–September'),('Gaurī','Pārvatī as “the fair one”; worshipped as Svarṇa Gaurī, golden Gaurī'),('Who keeps it','Married women above all; also girls hoping for a good marriage'),('Image','Gaurī in clay, metal, or invoked in a kalaśa; often “brought” from a well or tank'),('Thread','A thread of sixteen knots, worshipped and tied'),('Gifts','Bāgina in winnows; parents’ gifts to married daughters'),('Same day','Hartālikā Tīj in the north and Maharashtra')],svg(560,140,'Gaurī and Gaṇeśa side by side with bāgina',f'<rect width="560" height="140" fill="#f6e3e1"/>'+g(230,130,1.2,GAU())+g(320,130,1.1,ganesha())+g(120,130,1.2,mora())+g(450,130,1.2,mora()))),
 reading('who','WHO IS GAURĪ?','The fair one, the mother of Gaṇeśa',svg(560,160,'Gaurī seated with a lotus, Śiva and the child Gaṇeśa beside her on a mountain',f'<rect width="560" height="160" fill="#e3eaf3"/>'+g(280,160,1.4,mountain('#c9d6e6',True))+g(240,150,1,shiva())+g(310,150,1,GAU())+g(370,150,.8,ganesha(seat=False))),['<b>Gaurī.</b> <i>Gaurī</i> means “the fair, the bright one”: a name of <b>Pārvatī</b>, daughter of the mountain king Himavān, wife of Śiva, mother of Gaṇeśa and Skanda. In the Devī Māhātmya the gods call her Gaurī in their greatest hymn (two pages on).','<b>Svarṇa Gaurī.</b> On the festival she is worshipped as <b>Svarṇa Gaurī</b>, golden Gaurī, the giver of a happy married life, long life to husbands, and good fortune (<i>saubhāgya</i>).','<b>The daughter.</b> Karnataka imagines her coming to her parents’ home, as every married daughter comes for festivals; that is why the whole day feels like a family visit.','<b>Mother and son.</b> She is also Gaṇeśa’s mother: she made him from the turmeric of her own body (read our '+L('/ganesha/festivals/ganesha-chaturthi/','Gaṇeśa Caturthī')+' article). The next day he comes for her.'],[('z','A goddess visiting her parents?'),('b','Like every married daughter at festival time, Zappy. That’s why it feels so homely.')],'The fair one <b>comes home</b>.'),
 story('tapas','APARṆĀ: GAURĪ’S PENANCE','How she won Śiva',strip('Three panels: Pārvatī meditating in the snow; living on leaves, then nothing; Śiva appearing as a young ascetic and then in his own form',[panel([(GAU(),1),(mountain('#e3eaf3',True),.6)],'#e3eaf3',150),panel([(GAU(),1),(leaf(),1)],'#fff3cf',150),panel([(sage('#ff8c1a'),.8),(shiva(),.8),(GAU(),.8)],'#f6e3e1',150)],['the snows','not even a leaf','the test']),'Śiva Purāṇa, Rudra Saṃhitā, Pārvatī Khaṇḍa; Kālidāsa’s Kumārasambhava, canto 5.',['Śiva, after Satī’s death, sat in meditation and would not look at the world. Even Kāma’s arrow failed (read our '+L('/festivals/holi/','Holi')+' article).','So <b>Pārvatī</b> went into the snows and undertook penance herself, harder than any sage’s: summer among fires, winter in icy water, living on fallen leaves, and at last not even leaves: hence the name <b>Aparṇā</b>, “without even a leaf”.','A young brahmacārin came to her hermitage and mocked Śiva: a ghost-loving beggar with ash and snakes, why waste your youth on him?','Pārvatī answered him with fire and turned to leave: she would not listen to a word against Śiva. The young man took her hand: it was Śiva himself.','Their marriage followed (told in our '+L('/festivals/maha-shivaratri/','Mahāśivarātri')+' article). Gaurī is worshipped by women as the one who won her husband by her own strength of will.'],[('z','She didn’t eat for how long?'),('b','The poets don’t count, Zappy. The point is that she chose, and wouldn’t let go.')],'A will <b>stronger than any sage’s</b>.'),
 verse('v-gauri','Devī Māhātmya 11.10','The gods’ greatest verse to Gaurī',['sarvamaṅgalamāṅgalye śive sarvārthasādhike','śaraṇye tryambake gauri nārāyaṇi namo ’stu te'],svg(200,150,'Gaurī with three eyes and a lamp before her',f'<rect width="200" height="150" fill="#f6e3e1"/>'+g(100,140,1.3,GAU())+g(40,140,1.2,lamp())+g(160,140,1.2,lamp())),'O auspiciousness in all that is auspicious, O Śivā, accomplisher of every aim, O refuge, three-eyed Gaurī, Nārāyaṇī, salutations to you.',[('sarva-maṅgala-māṅgalye','the auspiciousness of all that is auspicious'),('śive','O Śivā, the gracious'),('sarva-artha-sādhike','fulfiller of every aim'),('śaraṇye','O refuge'),('tryambake','O three-eyed one'),('gauri','O Gaurī')],'<b>The verse of the day.</b> From the Nārāyaṇī stuti of the Devī Māhātmya, this is the verse most Karnataka women say before Gaurī. It calls her <i>maṅgala</i>, auspiciousness itself, the exact gift the Svarṇa Gaurī vrata asks for: a home full of good fortune.',k='The <b>auspicious in all</b> that is auspicious.',note='Text as on our '+L('/devi/devi-mahatmya/part-16/','Devī Māhātmya, part 16')+' page (chapter 11, verse 10).'),
 reading('arrival','BRINGING GAURĪ HOME','The first day',svg(560,170,'Women in silk saris carrying Gaurī on a plate from a tank toward a house with a rangoli',f'<rect width="560" height="170" fill="#f6e3e1"/>'+'<rect y="140" width="560" height="30" fill="#e9c9c3"/>'+g(100,140,1.2,tank())+g(230,145,1,person('#c0392b'))+g(230,100,.8,gauri_plate())+g(280,145,1,person('#e0a800'))+'<rect x="400" y="60" width="120" height="85" fill="#c9a06a"/>'+g(460,150,.8,rangoli())),['<b>From the water.</b> In many families Gaurī is “brought” from water: the women go to a well, tank or river, invoke her in a little turmeric or sand image (<b>jalagaurī</b>) or a kalaśa, and carry her home on a plate with songs, as a daughter is brought home.','<b>The maṇṭapa.</b> At home she is set on a decorated platform framed with banana stems, mango leaves and flowers, often on a bed of rice or grains, dressed in a little sari and jewellery. Many families use a metal or clay Gaurī that is a family heirloom.','<b>The pūjā.</b> The married women of the house worship her with turmeric, kuṅkuma, flowers, the sixteen services, and the vrata kathā. Many fast until the evening worship.','<b>The thread.</b> A yellow thread of sixteen knots (<i>dāra</i>), worshipped with her, is tied on each woman’s right wrist or worn round the neck.'],[('z','Gaurī comes out of a well?'),('b','She’s invoked there, Zappy, then carried home like a bride on her festival visit. Every village does it a little differently.')],'Carried home <b>like a daughter</b>.'),
 story('vrata','THE SVARṆA GAURĪ VRATA KATHĀ','The thread that was thrown away',strip('Three panels: a queen tying the sacred thread; the other queen throwing her thread into a dry tree; the tree drying and her fortunes falling, until she keeps the vow again',[panel([(person('#c0392b'),1),(thread16(),.8)],'#fff3cf',150),panel([(person('#7a3fa0'),1),(tree('#8a6a3a'),.8)],'#e9d6c0',150),panel([(person('#7a3fa0'),.9),(GAU(),.8)],'#f6e3e1',150)],['the vow kept','the thread thrown','the vow restored']),'The story read at the end of the worship, as told in Svarṇa Gaurī vrata booklets; versions differ.',['A king, <b>Candraprabha</b> in many tellings, had two queens. One day Gaurī herself, the story says, taught the elder queen the Svarṇa Gaurī vrata and the sixteen-knot thread.','The elder queen kept the vow faithfully and wore the thread. The younger, proud, mocked it, tore off her thread and threw it into a dry tree in the garden.','The dry tree burst into leaf where the thread fell, while the younger queen’s fortunes withered: the king turned from her, her wealth and health left her, and she wandered in misery.','At last she understood, sought out the goddess with the help of the elder queen, kept the vow with humility, and tied the thread again.','Gaurī forgave her, and her home was restored. The kathā ends: keep the vow every year, honour the thread, and never mock what others hold sacred.'],[('z','The thread made a dead tree grow?'),('b','So says the story, Zappy. Its real point is the younger queen’s pride, and how she got over it.')],'Pride undone, <b>the thread retied</b>.'),
 cards('bagina','BĀGINA','Gifts of good fortune in a winnow',fig_row('A bāgina winnow with turmeric, kuṅkuma, bangles, black beads, comb, mirror and coconut',[(mora(),1.8),('<circle cx="-10" r="9" fill="#e0a800"/><circle cx="10" r="9" fill="#c0392b"/>',1.6),('<circle r="14" fill="none" stroke="#2a9d6f" stroke-width="4"/><circle r="10" fill="none" stroke="#c0392b" stroke-width="4"/>',1.4),(coconut(),1.5)],['mora','arisina-kuṅkuma','baḷe','tenginakāyi'],gy=150),[('🧺','The tray','A small winnow (<b>mora</b>), painted with turmeric, holds the gifts; a second is placed over it as a lid. One bāgina is offered to Gaurī and set aside.'),('🎁','What’s inside','Turmeric, kuṅkuma, bangles, black beads (<i>kariamaṇi</i>), a comb, a mirror, a blouse piece, coconut, grains, dal, jaggery and fruit: the marks of a happy home.'),('👰','New brides','A newly married woman gives sixteen pairs of bāgina to married women in her first year and receives their blessings.'),('🗣️','The words','The bāgina is given with traditional phrases, and received with both hands and a blessing in return.')],[('z','What’s inside?'),('b','Turmeric, kuṅkuma, bangles, black beads, a comb, a mirror, coconut, grains, jaggery, Zappy: the marks of a happy home.')],'Good fortune, <b>given in pairs</b>.'),
 reading('tavaru','THE MOTHER’S HOME','Gifts from parents, daughters visiting',svg(560,160,'Parents handing a gift bundle to their married daughter at their door',f'<rect width="560" height="160" fill="#f6e3e1"/>'+'<rect y="135" width="560" height="25" fill="#e9c9c3"/>'+'<rect x="60" y="40" width="160" height="100" fill="#c9a06a"/>'+g(170,140,1,god('#7a3fa0'))+g(210,140,1,mother('#2a9d6f'))+g(320,140,1.1,person('#c0392b'))+g(270,110,1,'<rect x="-14" y="-12" width="28" height="18" fill="#e0a800"/>')),['<b>Tavaru.</b> In Kannada the married woman’s parental home is her <b>tavaru</b>, and Gaurī habba is above all a tavaru festival.','<b>Gauri bāgina from parents.</b> Parents send their married daughters gifts for the festival: a sari, bangles, turmeric and kuṅkuma, sweets, or money in their place. In many families brothers carry them.','<b>Visits.</b> Daughters come home if they can, especially in the first year of marriage, exactly as Gaurī visits Himavān’s house.','<b>The meaning.</b> The festival keeps families close across the distance marriage puts between them. Many women remember Gaurī habba above all as the day their mother’s gift arrived.'],[('z','So it’s about families too?'),('b','Very much, Zappy. Gaurī habba is a family reunion with a goddess as chief guest.')],'A festival of <b>the mother’s home</b>.'),
 reading('ganesha','THE SECOND DAY: GAṆEŚA ARRIVES','The son comes for his mother',svg(560,160,'Gaṇeśa arriving on his mouse at the door where Gaurī waits',f'<rect width="560" height="160" fill="#f6e3e1"/>'+'<rect y="135" width="560" height="25" fill="#e9c9c3"/>'+g(200,140,1.2,GAU())+g(360,140,1.2,ganesha(seat=False))+g(400,148,.9,mouse())),['<b>Gaṇeśa Caturthī.</b> On the fourth day a clay Gaṇeśa is brought home and installed beside Gaurī, or in a neighbourhood pandal, with 21 leaves, 21 blades of dūrvā and 21 modakas. The full day is in our '+L('/ganesha/festivals/ganesha-chaturthi/','Gaṇeśa Caturthī')+' article.','<b>The telling.</b> In Karnataka he comes, as the story goes, to take his mother home to Kailāsa after her visit: the son fetching the mother.','<b>The moon.</b> That night eyes stay down: the moon laughed at Gaṇeśa once, and was cursed for it.','<b>Together.</b> Gaurī and Gaṇeśa are often immersed together at the end of the festival: one, three, five or more days later, in a well, tank, lake or a bucket at home.'],[('z','He comes to take her home?'),('b','That’s the Karnataka telling, Zappy. Mother visits; son fetches her; both leave together.')],'Mother and son <b>leave together</b>.'),
 cards('food','THE GAURĪ-GAṆEŚA KITCHEN','Kaḍubu, pañcakajjāya and hōḷige',fig_row('Kaḍubu, a bowl of pañcakajjāya, hōḷige and cakkuli',[(modaka(),2),(plate(),1.6),(laddu('#e0a800'),1.8),('<path d="M0 0 m-14 0 a14 14 0 1 0 28 0 a10 10 0 1 0 -20 0" fill="none" stroke="#c98a3a" stroke-width="4"/>',1.4)],['kaḍubu','pañcakajjāya','hōḷige','cakkuli'],gy=150),[('🥟','Kaḍubu','Steamed dumplings, sweet (coconut-jaggery) or savoury (dal), the heart of the festival kitchen; the Mudgala Purāṇa’s meditation verse for Taruṇa Gaṇapati names them.'),('🥣','Pañcakajjāya','“Five-mix”: roasted gram, coconut, sesame, jaggery and ghee, mixed by hand and offered first.'),('🫓','Hōḷige','Sweet flatbread with dal and jaggery, often made for Gaurī.'),('🍘','Fried treats','Cakkuli, karjikāyi and kōḍubaḷe for the guests and the bāgina visitors.')],[('z','Kaḍubu again!'),('b','Karnataka’s favourite Gaṇeśa food has scripture behind it, Zappy. And a grandmother behind every batch.')],'Steamed, mixed <b>and shared</b>.'),
 reading('hartalika','HARTĀLIKĀ IN THE NORTH','The same day, another story',svg(560,160,'Two friends leading Pārvatī away into a forest, with a liṅga of sand',f'<rect width="560" height="160" fill="#e3f5e9"/>'+''.join(g(x,150,.8,tree()) for x in (60,480,520))+g(200,150,1,person('#e0a800'))+g(260,150,1,GAU())+g(320,150,1,person('#7a3fa0'))+g(420,150,.7,linga())),['<b>Hartālikā Tīj.</b> In north and central India and Maharashtra the same Tṛtīyā is <b>Hartālikā</b>, from <i>harita</i> (taken away) and <i>ālikā</i> (by her friends).','<b>The story.</b> Himavān had promised Pārvatī to Viṣṇu. To save her for Śiva, her friends led her secretly into the forest, where she made a liṅga of sand and worshipped it on this day; Śiva was pleased and accepted her.','<b>The vow.</b> Women fast, many without water, for a happy marriage, worship Śiva and Pārvatī made of sand or clay, and stay awake through the night.','<b>Same love.</b> Hartālikā and Svarṇa Gaurī are two tellings of one devotion: Gaurī’s will to choose her own husband, and the blessings she gives women.'],[('z','Same day, different festival?'),('b','Same goddess, same day, different story, Zappy. India keeps both.')],'Taken away <b>by her friends</b>.'),
 reading('meaning','WHAT GAURĪ-GAṆEŚA MEANS','Home, mother and son',svg(560,150,'Gaurī and Gaṇeśa together on a decorated platform with lamps',f'<rect width="560" height="150" fill="#f6e3e1"/>'+'<rect x="150" y="110" width="260" height="20" fill="#c9a06a"/>'+g(240,110,1.1,GAU())+g(320,112,1,ganesha())+g(110,130,1.3,lamp())+g(450,130,1.3,lamp())),['<b>Women’s festival.</b> Gaurī habba is one of the few great festivals run by women for women: the vow, the bāgina, the gifts from home. It honours the married woman’s two families at once.','<b>Choice and strength.</b> Gaurī won Śiva by her own penance; the vrata asks for her strength as well as her blessing. (Interpretation.)','<b>The family.</b> Daughter visiting parents, son fetching mother: the festival plays out the year’s most loving journeys.','<b>Auspiciousness.</b> <i>Sarvamaṅgalamāṅgalye</i>: what the day asks for is maṅgala, a good, whole, happy home.'],[('z','If I could do one thing for Gaurī habba?'),('b','Call or visit your mother’s home, Zappy, and take a small gift, turmeric and kuṅkuma or just sweets. That’s the festival.')],'A festival of <b>the whole family</b>.'),
 end(i,['<b>When.</b> Bhādrapada Śukla Tṛtīyā (Gaurī) and Caturthī (Gaṇeśa).','<b>Gaurī.</b> Pārvatī the fair; Aparṇā who won Śiva; Svarṇa Gaurī.','<b>Rite.</b> Brought from water, sixteen-knot thread, vrata kathā, DM 11.10.','<b>Bāgina.</b> Gifts in winnows to married women; parents’ gifts to daughters.','<b>Next day.</b> Gaṇeśa comes for his mother; both leave together.'],'Previous: '+L('/ganesha/forms/yuga-avatars/','the four yuga avatāras')+'. Next: '+L('/ganesha/festivals/ganesha-chaturthi/','Gaṇeśa Caturthī')+'.','Gaurī-Gaṇeśa habba'),
 sources([('Texts:','Śiva Purāṇa, Rudra Saṃhitā, Pārvatī Khaṇḍa and Kālidāsa’s Kumārasambhava, canto 5 (Aparṇā); Devī Māhātmya 11.10 (our part 16 page). Svarṇa Gaurī vrata kathā from vrata booklets.'),('Customs:','Karnataka practice (jalagaurī, sixteen-knot thread, bāgina, tavaru gifts, kaḍubu) as summarised in our earlier guide; Hartālikā from general references.')],'the vrata kathā (booklet versions; king’s name and details vary); jalagaurī practice (varies by family and region); bāgina contents and number (vary); the Mudgala Purāṇa kaḍubu verse (as cited in our Gaṇeśa forms pages).','Interpretations are marked as such.')]
build(i,'MOTHER FIRST · BĀGINA · THE SIXTEEN-KNOT THREAD',COV,'Gaurī, then Gaṇeśa','Who <b>Gaurī</b> is and how she won Śiva, the <b>vrata</b> and its story, the great verse to her, <b>bāgina</b> and the mother’s home, and the second day when Gaṇeśa comes for his mother.','Gaurī-Gaṇeśa habba explained: Bhādrapada Tṛtīyā and Caturthī in Karnataka, Gaurī as Pārvatī and Aparṇā, the Svarṇa Gaurī vrata and its kathā, Devī Māhātmya 11.10, jalagaurī, the sixteen-knot thread, bāgina, gifts to married daughters, kaḍubu and Hartālikā Tīj.',pp)
print('gg ok',len(pp)+2)
